const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=n=>Number(n||0).toLocaleString('en-IN'),date=s=>s?new Date(s).toLocaleDateString('en-GB',{timeZone:'Asia/Kolkata'}):'—',icon=n=>`<span class="material-symbols-outlined" style="font-size:17px">${n}</span>`;let state={boot:null,client:null,records:[],connections:[],jobs:[],tab:new URLSearchParams(location.search).get('tab')||'',query:'',filters:{},exportRecords:[]},route=document.body.dataset.route||'client-dashboard',dialog,toastTimer;
const routeNames={'client-dashboard':'Client Dashboard','all-clients':'All Clients','client-setup':'Client Setup & Connections','keyword-research':'Keyword Research','site-audit':'Site Audit','fixes-and-approvals':'Fixes & Approvals','developer-tickets':'Developer Tickets','content-studio':'Content Studio','aeo-visibility':'AEO Visibility','schema-generator':'Schema Generator','monthly-plan':'Monthly Plan & Content Refresh','reports-admin':'Reports & Administration','admin':'Admin Dashboard'};
async function api(path,method='GET',data){const response=await fetch('/api/'+path,{method,headers:method==='GET'?{}:{'Content-Type':'application/json'},...(data?{body:JSON.stringify(data)}:{})});let body;try{body=await response.json()}catch{throw Error('Server response was unavailable. Please retry.')}if(!response.ok){const e=Error(body.error||'Request failed');e.status=response.status;throw e;}return body}
const canEdit=()=>['admin','seo_lead'].includes(state.boot?.user.role),canApprove=()=>['admin','head'].includes(state.boot?.user.role),admin=()=>state.boot?.user.role==='admin';
