function modal(title,html){$('#work-dialog-title').textContent=title;$('#work-dialog-body').innerHTML=html;$('#work-dialog-error').textContent='';$('#work-dialog-error').hidden=true;if(!dialog.open)dialog.showModal();dialog.querySelector('input,textarea,select')?.focus()}
