 const make={Organization:()=>({'@type':'Organization',name:f.name,url:c.url,logo:f.logo,telephone:f.telephone,email:f.email,sameAs:lines(f.sameAs)}),LocalBusiness:()=>({'@type':'LocalBusiness',name:f.name,url:c.url,telephone:f.telephone,image:f.image,priceRange:f.priceRange,openingHours:f.hours,address:{'@type':'PostalAddress',streetAddress:f.street,addressLocality:f.city,addressRegion:f.region,postalCode:f.postal,addressCountry:f.country}}),Article:()=>({'@type':'Article',headline:f.headline,description:f.description,image:f.image,datePublished:f.datePublished,dateModified:f.dateModified,author:{'@type':'Person',name:f.author},publisher:{'@type':'Organization',name:c.name,url:c.url},mainEntityOfPage:url}),FAQPage:()=>null,Product:()=>({'@type':'Product',name:f.name,description:f.description,image:f.image,brand:{'@type':'Brand',name:f.brand},offers:f.price?{'@type':'Offer',price:f.price,priceCurrency:f.currency,url}:undefined}),BreadcrumbList:()=>({'@type':'BreadcrumbList',itemListElement:lines(f.crumbs).map((l,i)=>{const [n,u]=l.split('|').map(x=>x.trim());return{'@type':'ListItem',position:i+1,name:n,item:u}})}),Event:()=>({'@type':'Event',name:f.name,startDate:f.startDate,endDate:f.endDate,location:{'@type':'Place',name:f.place,address:f.address}})};
 const nodes=[],main=make[s.type]();if(main){main['@id']=url.replace(/#.*$/,'')+'#'+s.type.toLowerCase();nodes.push(clean(main))}
