  +(sameUrl.length?`<section class="plan-banner warn">${icon('warning')}<div><b>Possible duplicate schema</b><span>${sameUrl.length} saved ${esc(s.type)} schema${sameUrl.length>1?'s':''} already target this URL. Check the live page (Yoast / Rank Math may also output schema) before adding another.</span></div></section>`:'')
