  +(T.fields.length?`<section class="panel"><div class="panel-top"><h2><span class="material-symbols-outlined panel-icon">${T.icon}</span><span>${esc(s.type)} properties</span></h2><span class="mono-sub">Use facts visible on the page</span></div><div class="sf-grid">${T.fields.map(inp).join('')}</div></section>`:'')
  +faqBlock+`</div><aside class="sch-side"><section class="panel"><div class="panel-top"><h2><span class="material-symbols-outlined panel-icon">verified</span><span>Validation status</span></h2><span id="sch-badge" class="tag">Checking…</span></div><div class="score-tiles"><div><span>Errors</span><b id="sch-err">–</b></div><div><span>Recommended missing</span><b id="sch-warn">–</b></div><div><span>Nodes</span><b id="sch-nodes">–</b></div></div><div id="sch-msgs"></div></section><section class="panel code-panel"><div class="panel-top"><h2><span class="material-symbols-outlined panel-icon">data_object</span><span>JSON-LD output</span></h2>${btn(icon('content_copy')+'Copy','sch-copy')}</div><pre class="code" id="sch-json"></pre></section><section class="panel"><label class="check dup"><input type="checkbox" data-sfu="dup" ${s.dup?'checked':''}><span>I checked the live page: this will not duplicate schema already on it (theme, Yoast, Rank Math).</span></label><p class="mono-sub" style="margin-top:10px">${icon('verified_user')} Safe mode: saved schema goes to review; after approval it becomes a WordPress fix that needs its own approval.</p></section></aside></div>`
