function schRefresh(c){const s=state.sch,json=schBuild(s,c),out=$('#sch-json');if(!out)return;out.textContent=JSON.stringify(json,null,2);const nodes=json['@graph']||[json],T=SCH_TYPES[s.type],miss=T.rec.filter(k=>!String(s.f[k]||'').trim());$('#sch-nodes').textContent=nodes.filter(n=>n['@type']).length;$('#sch-warn').textContent=miss.length;clearTimeout(schTimer);schTimer=setTimeout(async()=>{try{const v=await api('validate','POST',{type:'schema',json});if(!$('#sch-err'))return;$('#sch-err').textContent=v.passed?0:v.errors.length;const b=$('#sch-badge');b.className='tag '+(v.passed?'good':'bad');b.textContent=v.passed?'Valid':'Fix errors';$('#sch-msgs').innerHTML=(v.passed?'':v.errors.map(e=>`<div class="gate fail"><span class="material-symbols-outlined">cancel</span><span class="gate-name">${esc(e)}</span></div>`).join(''))+miss.map(k=>`<div class="gate warnrow"><span class="material-symbols-outlined">info</span><span class="gate-name">Recommended: ${esc((T.fields.find(f=>f[0]===k)||[k,k])[1])}</span></div>`).join('')+(v.passed&&!miss.length?'<div class="gate pass"><span class="material-symbols-outlined">check_circle</span><span class="gate-name">Required and recommended fields present.</span></div>':'')}catch(e){}},300)}
