async function adminDecide(ids,action,note){const o=state.adminData,out={ok:0,fail:[]};for(const id of ids){const p=o.pending.find(x=>x.id===id);if(!p)continue;try{const res=await api('records/'+id+'/action','POST',{action,revision:p.revision,...(action==='reject'?{reason:note}:{})});if(res.auto_apply_error)out.fail.push(p.title+': approved, but not applied: '+res.auto_apply_error);else out.ok++}catch(e){out.fail.push(p.title+': '+e.message)}}state.adminSel=new Set();await hydrateAdminDashboard($('main'));toast(`${out.ok} ${action==='approve'?'approved':'rejected'}${out.fail.length?' · '+out.fail.length+' failed: '+out.fail[0]:''}`)}
